// The HTTP Request node's array-splitting behaviour for a top-level JSON array
// response has varied across n8n versions, so don't assume it always turns one
// PostgREST array into one item per row. Normalize defensively here: flatten any
// array-shaped item.json into individual rows, drop anything without an id.
const inputItems = $input.all();
const rows = [];
for (const item of inputItems) {
  const value = item.json;
  if (Array.isArray(value)) {
    rows.push(...value);
  } else if (value) {
    rows.push(value);
  }
}
return rows.filter(row => row && row.id).map(row => ({ json: row }));

// THE DOUBLE-PUBLISH GUARD. Claim Post PATCHes with ?id=eq.{id}&status=eq.scheduled,
// so PostgREST only returns a row if THIS run's claim actually matched. If another
// overlapping run claimed the same row first, the WHERE clause matches nothing and
// the PATCH response is an empty array -- even though the HTTP call itself succeeded.
//
// Any item whose claim response came back empty is dropped here, silently, on purpose.
// It must NOT be published again -- some other execution already owns it. This is the
// single enforcement point standing between this workflow and double-posting to a
// customer's Instagram or Facebook. Do not remove this filter.
//
// pairedItem is set explicitly (by input index) so downstream nodes can still resolve
// $('Drop Unclaimed Posts').item on the surviving items after this filter runs.
const items = $input.all();
const kept = [];
items.forEach((item, index) => {
  const raw = item.json;
  const row = Array.isArray(raw) ? raw[0] : raw;
  if (row && row.id) {
    kept.push({ json: row, pairedItem: index });
  }
});
return kept;

// Only reached when a publish node errored at the transport level. Normal
// responses - including unparseable ones - go to 'Interpret Publish Result'.
const body = $input.item.json || {};
const message = (body.error && (body.error.message || body.error)) || body.message || JSON.stringify(body);
return { json: { id: $('Drop Unclaimed Posts').item.json.id, last_error: String(message).slice(0, 500) } };

// Three outcomes, not two. Treating "we couldn't read the reply" as a failure is
// dangerous: 'failed' invites a retry, and a retry double-posts to a real account.
// Only an explicit success or an explicit failure is trusted; anything else goes
// to a human as needs_review.
const res = $input.item.json || {};
const status = Number(res.statusCode || res.status || 0);
const rawBody = typeof res.body === 'string' ? res.body : JSON.stringify(res.body ?? '');
const claimedId = $('Drop Unclaimed Posts').item.json.id;

let parsed = null;
try { parsed = rawBody ? JSON.parse(rawBody) : null; } catch (e) { parsed = null; }

if (parsed && parsed.success === true) {
  return { json: { id: claimedId, outcome: 'published', post_id: parsed.post_id || null, last_error: null } };
}
if (parsed && parsed.success === false) {
  return { json: { id: claimedId, outcome: 'failed', post_id: null,
    last_error: String(parsed.error || 'Publish webhook reported failure').slice(0, 500) } };
}
const detail = rawBody ? rawBody.slice(0, 300) : ('HTTP ' + status + ' with empty body');
return { json: { id: claimedId, outcome: 'needs_review', post_id: null,
  last_error: ('Publish reply could not be parsed (HTTP ' + status + '). CHECK THE ACCOUNT - this may already be live. Reply was: ' + detail).slice(0, 500) } };
